contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, address secondCaller) public payable {
        require(newOwner != address(0), "newOwner must be nonzero for a meaningful success");

        bool firstReverted;
        bool firstSuccess;
        address beforeAdmin = msg.sender;

        try c.setOwner(newOwner) returns (bool s) {
            firstReverted = false;
            firstSuccess = s;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, secondCaller));
        if (!ok) {
            secondReverted = true;
        } else {
            secondReverted = false;
            require(data.length == 32, "return data length");
            bool ret = abi.decode(data, (bool));
            require(ret == true, "successful setOwner must return true");
        }

        assert(
            !firstReverted && firstSuccess
            ? (secondReverted || c.owner() == secondCaller || beforeAdmin != address(this))
            : true
        );
    }

    receive() external payable {}
}

